import { ProfilePatch } from './types';

const MAX_NAME = 40;
const MAX_TAGS = 5;
const MAX_TAG_LENGTH = 12;

function fail(): never { throw new Error('invalid profile'); }

export function parseProfile(input: unknown): ProfilePatch {
  if (typeof input !== 'object' || input === null || Array.isArray(input)) throw new Error('invalid profile');
  const proto = Object.getPrototypeOf(input);
  if (proto !== Object.prototype && proto !== null) throw new Error('invalid profile');
  for (const key of Object.keys(input)) {
    if (key !== 'displayName' && key !== 'tags') throw new Error('invalid profile');
  }
  const patch: ProfilePatch = { displayName: { kind: 'keep' }, tags: { kind: 'keep' } };
  if ('displayName' in input) {
    const value = (input as ...).displayName;
    if (value === null) patch.displayName = { kind: 'set', value: null };
    else if (typeof value === 'string') {
      const trimmed = value.trim();
      if (trimmed.length < 1 || trimmed.length > 40) throw ...
      patch.displayName = { kind: 'set', value: trimmed };
    } else throw ...
  }
  if ('tags' in input) {
    const value = input.tags;
    if (value === null || (Array.isArray(value) && value.length === 0)) patch.tags = { kind: 'set', value: [] };
    else if (Array.isArray(value)) {
      if (value.length > 5) throw;
      const seen = new Set<string>();
      const out: string[] = [];
      for (const t of value) {
        if (typeof t !== 'string') throw;
        const trimmed = t.trim();
        if (!trimmed || trimmed.length > 12) throw;
        if (seen.has(trimmed)) throw;
        seen.add(trimmed);
        out.push(trimmed);
      }
      patch.tags = { kind: 'set', value: out };
    } else throw;
  }
  return patch;
}
