import { ProfilePatch } from './types';

const MAX_DISPLAY_NAME_LENGTH = 40;
const MAX_TAGS = 5;
const MAX_TAG_LENGTH = 12;

function invalid(): never {
  throw new Error('invalid profile');
}

export function parseProfile(input: unknown): ProfilePatch {
  if (typeof input !== 'object' || input === null || Array.isArray(input)) invalid();
  const record = input as Record<string, unknown>;
  const prototype = Object.getPrototypeOf(record);
  if (prototype !== Object.prototype && prototype !== null) invalid();
  for (const key of Object.keys(record)) {
    if (key !== 'displayName' && key !== 'tags') invalid();
  }

  const patch: ProfilePatch = { displayName: { kind: 'keep' }, tags: { kind: 'keep' } };

  if ('displayName' in record) {
    const value = record.displayName;
    if (value === null) {
      patch.displayName = { kind: 'set', value: null };
    } else if (typeof value === 'string') {
      const trimmed = value.trim();
      if (trimmed.length < 1 || trimmed.length > MAX_DISPLAY_NAME_LENGTH) invalid();
      patch.displayName = { kind: 'set', value: trimmed };
    } else {
      invalid();
    }
  }

  if ('tags' in record) {
    const value = record.tags;
    if (value === null || (Array.isArray(value) && value.length === 0)) {
      patch.tags = { kind: 'set', value: [] };
    } else if (Array.isArray(value)) {
      if (value.length > MAX_TAGS) invalid();
      const seen = new Set<string>();
      const tags: string[] = [];
      for (const entry of value) {
        if (typeof entry !== 'string') invalid();
        const trimmed = entry.trim();
        if (trimmed.length < 1 || trimmed.length > MAX_TAG_LENGTH) invalid();
        if (seen.has(trimmed)) invalid();
        seen.add(trimmed);
        tags.push(trimmed);
      }
      patch.tags = { kind: 'set', value: tags };
    } else {
      invalid();
    }
  }

  return patch;
}
